class PubSub {
  constructor() { this.channels = {}; }
  subscribe(ch, fn) {
    (this.channels[ch] = this.channels[ch] || []).push(fn);
  }
  publish(ch, data) {
    (this.channels[ch] || []).forEach(fn => fn(data));
  }
}
const ps = new PubSub();
ps.subscribe('news', (d) => console.log(d));
ps.publish('news', 'breaking');
